TEE_Result generate_key_for_object(unsigned long obj,
                                   unsigned long key_size,
                                   const struct utee_attribute* usr_params,
                                   unsigned long param_count) {
    TEE_Result result = TEE_SUCCESS;
    void* session = NULL;
    struct key_attributes* attributes = NULL;

    session = TEE_GetCurrentSession();
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    if (key_size < MIN_KEY_SIZE || key_size > MAX_KEY_SIZE) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    attributes = (struct key_attributes*)malloc(sizeof(struct key_attributes) * (param_count + 1));
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    // Copy user-defined parameters into the attributes
    for (unsigned long i = 0; i < param_count; ++i) {
        attributes[i] = *(struct key_attributes*)&usr_params[i];
    }

    switch (obj) {
        case TEE_OBJECT_TYPE_AES:
            result = generate_aes_key(session, key_size, attributes, param_count);
            break;
        case TEE_OBJECT_TYPE_RSA:
            result = generate_rsa_key(session, key_size, attributes, param_count);
            break;
        case TEE_OBJECT_TYPE_DSA:
            result = generate_dsa_key(session, key_size, attributes, param_count);
            break;
        default:
            result = TEE_ERROR_NOT_SUPPORTED;
            break;
    }

    if (attributes) {
        free(attributes);
    }

    return result;
}

TEE_Result generate_key(unsigned long obj,
                        unsigned long key_size,
                        const struct utee_attribute* usr_params,
                        unsigned long param_count) {
    TEE_Result result = TEE_SUCCESS;
    void* session = NULL;
    struct utee_attribute* attr_list = NULL;

    session = TEE_GetCurrentSession();
    if (!session) {
        return TEE_ERROR_GENERIC;
    }

    result = TEE_CheckObjectState(obj, session);
    if (result != TEE_SUCCESS) {
        return result;
    }

    attr_list = calloc(param_count, sizeof(struct utee_attribute));
    if (!attr_list) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attr_list, usr_params, param_count * sizeof(struct utee_attribute));

    if (key_size < MIN_KEY_SIZE || key_size > MAX_KEY_SIZE) {
        result = TEE_ERROR_BAD_PARAMETERS;
        goto cleanup;
    }

    if (is_rsa_object(obj)) {
        result = TEE_GenerateRSAKey(obj, key_size, attr_list, param_count);
    } else if (is_aes_object(obj)) {
        result = TEE_GenerateAESKey(obj, key_size, attr_list, param_count);
    } else if (is_dsa_object(obj)) {
        result = TEE_GenerateDSAKey(obj, key_size, attr_list, param_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

cleanup:
    if (attr_list) {
        free(attr_list);
    }

    return result;
}

TEE_Result generate_key_for_object(unsigned long obj,
                                   unsigned long key_size,
                                   const struct utee_attribute *usr_params,
                                   unsigned long param_count) {
    TEE_Result result = TEE_ERROR_GENERIC;
    struct tee_session *session = NULL;
    struct tee_object *object = NULL;
    struct utee_attribute *attributes = NULL;
    unsigned long attr_index = 0;

    session = tee_session_get_current();
    if (!session) {
        return TEE_ERROR_ACCESS_DENIED;
    }

    object = tee_object_manager_get_object(obj);
    if (!object || object->state != TEE_OBJECT_LIVE) {
        return TEE_ERROR_ITEM_NOT_FOUND;
    }

    if (key_size < object->min_key_size || key_size > object->max_key_size) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    attributes = calloc(param_count + 1, sizeof(struct utee_attribute));
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    for (attr_index = 0; attr_index < param_count; attr_index++) {
        attributes[attr_index] = *(usr_params + attr_index);
    }

    if (object->type == TEE_TYPE_AES) {
        result = tee_crypto_aes_key_gen(object, key_size, attributes, param_count);
    } else if (object->type == TEE_TYPE_RSA) {
        result = tee_crypto_rsa_key_gen(object, key_size, attributes, param_count);
    } else if (object->type == TEE_TYPE_DSA) {
        result = tee_crypto_dsa_key_gen(object, key_size, attributes, param_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

    free(attributes);
    return result;
}

TEE_Result generate_crypto_key(unsigned long obj,
                               unsigned long key_size,
                               const struct utee_attribute* usr_params,
                               unsigned long param_count) {
    TEE_Result result = TEE_SUCCESS;
    void* session = NULL;
    struct crypto_object* crypto_obj = NULL;
    struct utee_attribute* attributes = NULL;

    session = TEE_GetCurrentSession();
    if (!session) {
        return TEE_ERROR_BAD_STATE;
    }

    crypto_obj = get_crypto_object_by_id(obj);
    if (!crypto_obj) {
        return TEE_ERROR_ITEM_NOT_FOUND;
    }

    if (crypto_obj->state != OBJECT_STATE_INITIALIZED) {
        return TEE_ERROR_BAD_STATE;
    }

    if (key_size < crypto_obj->min_key_size || key_size > crypto_obj->max_key_size) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    attributes = calloc(param_count, sizeof(struct utee_attribute));
    if (!attributes) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attributes, usr_params, param_count * sizeof(struct utee_attribute));

    if (strcmp(crypto_obj->type, "AES") == 0) {
        result = generate_aes_key(crypto_obj, key_size, attributes, param_count);
    } else if (strcmp(crypto_obj->type, "RSA") == 0) {
        result = generate_rsa_key(crypto_obj, key_size, attributes, param_count);
    } else if (strcmp(crypto_obj->type, "DSA") == 0) {
        result = generate_dsa_key(crypto_obj, key_size, attributes, param_count);
    } else {
        result = TEE_ERROR_NOT_SUPPORTED;
    }

    free(attributes);

    if (result != TEE_SUCCESS) {
        crypto_obj->state = OBJECT_STATE_ERROR;
    }

    return result;
}

TEE_Result generate_key(unsigned long obj,
                        unsigned long key_size,
                        const struct utee_attribute *usr_params,
                        unsigned long param_count) {
    TEE_Result result = TEE_ERROR_GENERIC;
    struct utee_attribute *attrs = NULL;
    unsigned long attr_count = 0;

    if (!usr_params && param_count > 0) {
        return TEE_ERROR_BAD_PARAMETERS;
    }

    result = validate_key_size(obj, key_size);
    if (result != TEE_SUCCESS) {
        return result;
    }

    attrs = (struct utee_attribute *)malloc(param_count * sizeof(struct utee_attribute));
    if (!attrs) {
        return TEE_ERROR_OUT_OF_MEMORY;
    }

    memcpy(attrs, usr_params, param_count * sizeof(struct utee_attribute));

    switch (obj) {
        case TEE_OBJECT_TYPE_AES:
            result = generate_aes_key(attrs, param_count, key_size);
            break;
        case TEE_OBJECT_TYPE_RSA:
            result = generate_rsa_key(attrs, param_count, key_size);
            break;
        case TEE_OBJECT_TYPE_DSA:
            result = generate_dsa_key(attrs, param_count, key_size);
            break;
        default:
            result = TEE_ERROR_NOT_SUPPORTED;
            break;
    }

    if (result != TEE_SUCCESS) {
        free(attrs);
    }

    return result;
}
